cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block row and column
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Global row and column for the current thread
    int row = blockRow * TILE_SIZE + threadIdx.y;
    int col = blockCol * TILE_SIZE + threadIdx.x;

    // Accumulator for C(row, col)
    float Cvalue = 0.0f;

    // Shared memory for tiles of A and B
    __shared__ float shA[TILE_SIZE][TILE_SIZE];
    __shared__ float shB[TILE_SIZE][TILE_SIZE];

    // Loop over the K dimension
    for (int k_tile_idx = 0; k_tile_idx < (N + TILE_SIZE - 1) / TILE_SIZE; ++k_tile_idx) {
        // Load tiles into shared memory
        // Each thread loads one element
        int global_k_A = k_tile_idx * TILE_SIZE + threadIdx.x;
        int global_k_B = k_tile_idx * TILE_SIZE + threadIdx.y;

        // Ensure we are within bounds for A
        if (row < N && global_k_A < N) {
            shA[threadIdx.y][threadIdx.x] = A[row * N + global_k_A];
        } else {
            shA[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros
        }

        // Ensure we are within bounds for B
        if (global_k_B < N && col < N) {
            shB[threadIdx.y][threadIdx.x] = B[global_k_B * N + col];
        } else {
            shB[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros
        }

        __syncthreads();

        // Perform computation using the shared memory tiles
        for (int m = 0; m < TILE_SIZE; ++m) {
            Cvalue += shA[threadIdx.y][m] * shB[m][threadIdx.x];
        }

        __syncthreads();
    }

    // Write the result to global memory
    if (row < N && col < N) {
        C[row * N + col] = Cvalue;
    }
}
"""

cpp_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check if inputs are on CUDA
    AT_ASSERTM(A.is_cuda(), "A must be a CUDA tensor");
    AT_ASSERTM(B.is_cuda(), "B must be a CUDA tensor");

    // Get dimensions
    int N = A.size(0); // Assuming square matrices A and B (N, N)

    // Create output tensor C
    auto C = torch::zeros({N, N}, A.options());

    // Calculate grid and block dimensions
    int num_blocks_x = (N + TILE_SIZE - 1) / TILE_SIZE;
    int num_blocks_y = (N + TILE_SIZE - 1) / TILE_SIZE;
    dim3 gridDim(num_blocks_x, num_blocks_y);
    dim3 blockDim(TILE_SIZE, TILE_SIZE);

    // Launch the kernel
    matmul_kernel<<<gridDim, blockDim>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
